import heapq

def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)
    C = capacity
    K = max_swaps
    adj = [[] for _ in range(n)]
    for u, v, m, e in roads:
        adj[u].append((v, m, e))
    is_station = [False] * n
    for x in stations:
        if 0 <= x < n:
            is_station[x] = True

    W = C + 1
    H = K + 1
    INF = float('inf')
    dist = [INF] * (n * W * H)

    def idx(v, c, k):
        return (v * W + c) * H + k

    start = idx(s, C, 0)
    dist[start] = 0
    heap = [(0, s, C, 0)]
    while heap:
        d, u, c, k = heapq.heappop(heap)
        if d > dist[idx(u, c, k)]:
            continue
        # swap
        if is_station[u] and k < K:
            nd = d + swap_time
            j = idx(u, C, k + 1)
            if nd < dist[j]:
                dist[j] = nd
                heapq.heappush(heap, (nd, u, C, k + 1))
        for v, m, e in adj[u]:
            if e > 0 and c < e:
                continue
            nc = c - e
            if nc > C:
                nc = C
            nd = d + m
            j = idx(v, nc, k)
            if nd < dist[j]:
                dist[j] = nd
                heapq.heappush(heap, (nd, v, nc, k))

    best = None
    for c in range(W):
        for k in range(H):
            d = dist[idx(t, c, k)]
            if d < INF:
                cand = (d, k)
                if best is None or cand < best:
                    best = cand
    return best

def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative")
    n = len(messages)
    NEG = float('-inf')
    pc = [0] * (n + 1)  # pc[k] = number of pinned messages among the first k
    for i, (l, v, p) in enumerate(messages):
        pc[i + 1] = pc[i] + (1 if p else 0)

    best = None
    # Empty set: the whole list is one dropped run of length n.
    if n <= max_gap and pc[n] == 0:
        best = 0

    B = budget
    # dp[i][c]: best score with i kept as the last kept message, total length c.
    dp = []
    for i in range(n):
        L, v, p = messages[i]
        row = [NEG] * (B + 1)
        if L <= B:
            # i is the first kept message.
            if i <= max_gap and pc[i] == 0:
                row[L] = v
            for j in range(i - 1, max(-1, i - 2 - max_gap), -1):
                # No pinned message may lie strictly between j and i.
                if pc[i] - pc[j + 1] > 0:
                    break
                add = v + (bonus if j == i - 1 else 0)
                prev = dp[j]
                for c in range(B - L + 1):
                    pv = prev[c]
                    if pv != NEG:
                        val = pv + add
                        if val > row[c + L]:
                            row[c + L] = val
        dp.append(row)
        # i as the last kept message: the trailing run must be short enough
        # and contain no pinned message.
        if n - 1 - i <= max_gap and pc[n] - pc[i + 1] == 0:
            m = max(row)
            if m != NEG and (best is None or m > best):
                best = m
    return best

def min_pruning_cost(parent, demand, cap, cut_cost, critical, root_cap, penalty):
    INF = float('inf')
    n = len(parent)
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)
    # BFS order
    order = [0]
    for u in order:
        order.extend(children[u])
    S = [0] * n
    hascrit = [False] * n
    dp = [None] * n
    for v in reversed(order):
        S[v] = demand[v]
        hascrit[v] = bool(critical[v])
        cur = [INF] * (demand[v] + 1)
        cur[demand[v]] = 0
        for c in children[v]:
            S[v] += S[c]
            if hascrit[c]:
                hascrit[v] = True
            Sc = S[c]
            dc = dp[c]
            opt = [INF] * (Sc + 1)
            lim = min(cap[c], Sc)
            for l in range(lim + 1):
                opt[l] = dc[l]
            if not hascrit[c]:
                cc = cut_cost[c] + penalty * Sc
                if cc < opt[0]:
                    opt[0] = cc
            new = [INF] * (len(cur) + Sc)
            optitems = [(j, x) for j, x in enumerate(opt) if x != INF]
            for i, a in enumerate(cur):
                if a == INF:
                    continue
                for j, b in optitems:
                    t = a + b
                    if t < new[i + j]:
                        new[i + j] = t
            cur = new
            dp[c] = None
        dp[v] = cur
    best = INF
    d0 = dp[0]
    for l in range(min(root_cap, len(d0) - 1) + 1):
        if d0[l] < best:
            best = d0[l]
    return None if best == INF else int(best)

from bisect import bisect_left

def earliest_arrival(connections, transfer, source, target, start_time, max_boardings):
    if source == target:
        return start_time
    if max_boardings <= 0:
        return None
    INF = float('inf')
    n = len(transfer)

    trips = {}
    for c in connections:
        trips.setdefault(c[0], []).append(c)
    trip_list = []   # per trip: list of (to, arr)
    st_dep = [[] for _ in range(n)]
    st_info = [[] for _ in range(n)]
    tmp = [[] for _ in range(n)]
    for ti, (tid, lst) in enumerate(trips.items()):
        lst.sort(key=lambda c: c[3])
        trip_list.append([(c[2], c[4]) for c in lst])
        for pos, c in enumerate(lst):
            tmp[c[1]].append((c[3], ti, pos))
    for s in range(n):
        if tmp[s]:
            tmp[s].sort()
            st_dep[s] = [x[0] for x in tmp[s]]
            st_info[s] = [(x[1], x[2]) for x in tmp[s]]
    best_pos = [len(t) for t in trip_list]
    readyproc = [INF] * n

    best = INF
    frontier = {source: start_time}
    rounds = 0
    while frontier and rounds < max_boardings:
        rounds += 1
        pending = {}
        for s, r in frontier.items():
            prev = readyproc[s]
            deps = st_dep[s]
            lo = bisect_left(deps, r)
            hi = len(deps) if prev == INF else bisect_left(deps, prev)
            readyproc[s] = r
            info = st_info[s]
            for idx in range(lo, hi):
                ti, pos = info[idx]
                b = best_pos[ti]
                if pos >= b:
                    continue
                best_pos[ti] = pos
                tl = trip_list[ti]
                for j in range(pos, b):
                    to, arr = tl[j]
                    if to == target:
                        if arr < best:
                            best = arr
                    p = pending.get(to)
                    if p is None or arr < p:
                        pending[to] = arr
        frontier = {}
        for s, a in pending.items():
            r = a + transfer[s]
            if r < readyproc[s]:
                frontier[s] = r
    return None if best == INF else best

def run_lock_manager(ops):
    log = []
    holders = {}   # res -> {tx: mode}
    queues = {}    # res -> list of [tx, mode, is_upgrade]
    held = {}      # tx -> set of res
    waiting = {}   # tx -> res or None
    finished = set()

    def get_h(r):
        h = holders.get(r)
        if h is None:
            h = holders[r] = {}
            queues[r] = []
        return h

    def grantable(h, u, m):
        if m == 'S':
            for v, hm in h.items():
                if v != u and hm == 'X':
                    return False
            return True
        for v in h:
            if v != u:
                return False
        return True

    def process_queue(r, i):
        q = queues[r]
        h = holders[r]
        while q:
            u, m, up = q[0]
            if grantable(h, u, m):
                q.pop(0)
                h[u] = m
                held[u].add(r)
                waiting[u] = None
                log.append(("GRANT", i, u, r, m))
            else:
                break

    def release(t, i):
        affected = set(held.get(t, ()))
        wr = waiting.get(t)
        if wr is not None:
            q = queues[wr]
            for k in range(len(q)):
                if q[k][0] == t:
                    del q[k]
                    break
            waiting[t] = None
            affected.add(wr)
        for r in held.get(t, ()):
            holders[r].pop(t, None)
        held[t] = set()
        finished.add(t)
        for r in sorted(affected):
            process_queue(r, i)

    def edges(w):
        r = waiting[w]
        q = queues[r]
        idx = 0
        for k in range(len(q)):
            if q[k][0] == w:
                idx = k
                break
        mode = q[idx][1]
        out = []
        if idx > 0:
            out.append(q[idx - 1][0])
        for v, m in holders[r].items():
            if v != w and (mode == 'X' or m == 'X'):
                out.append(v)
        return out

    def find_victim(t):
        adj = {}
        seen = {t}
        stack = [t]
        reached = False
        while stack:
            u = stack.pop()
            if waiting.get(u) is None:
                adj[u] = []
                continue
            es = edges(u)
            adj[u] = es
            for v in es:
                if v == t:
                    reached = True
                if v not in seen:
                    seen.add(v)
                    stack.append(v)
        if not reached:
            return None
        rev = {}
        for u, es in adj.items():
            for v in es:
                rev.setdefault(v, []).append(u)
        back = {t}
        stack = [t]
        while stack:
            u = stack.pop()
            for p in rev.get(u, ()):
                if p not in back:
                    back.add(p)
                    stack.append(p)
        return max(back)

    for i, op in enumerate(ops):
        kind = op[0]
        t = op[1]
        if t in finished or waiting.get(t) is not None:
            log.append(("IGNORED", i, t))
            continue
        if t not in held:
            held[t] = set()
            waiting[t] = None
        if kind == "COMMIT":
            log.append(("COMMIT", i, t))
            release(t, i)
            continue
        m = kind
        r = op[2]
        h = get_h(r)
        q = queues[r]
        cur = h.get(t)
        if cur == 'X' or (cur == 'S' and m == 'S'):
            log.append(("HELD", i, t, r))
            continue
        if cur == 'S':  # upgrade
            if len(h) == 1:
                h[t] = 'X'
                log.append(("GRANT", i, t, r, "X"))
                continue
            pos = 0
            while pos < len(q) and q[pos][2]:
                pos += 1
            q.insert(pos, [t, 'X', True])
            waiting[t] = r
            log.append(("WAIT", i, t, r, "X"))
        else:
            if not q and grantable(h, t, m):
                h[t] = m
                held[t].add(r)
                log.append(("GRANT", i, t, r, m))
                continue
            q.append([t, m, False])
            waiting[t] = r
            log.append(("WAIT", i, t, r, m))
        # deadlock resolution
        while waiting.get(t) is not None:
            v = find_victim(t)
            if v is None:
                break
            log.append(("ABORT", i, v))
            release(v, i)
    return log

def simulate_vending(prices, stock, bank, events, timeout):
    # Validate time ordering before doing anything else
    prev = None
    for ev in events:
        t = ev[0]
        if prev is not None and t < prev:
            raise ValueError("events not in non-decreasing time order")
        prev = t

    DENOMS = (100, 25, 10, 5)
    ACCEPTED = (5, 10, 25, 100)

    b = {d: bank.get(d, 0) for d in ACCEPTED}
    st = dict(stock)
    escrow = []          # list of coin values (at most 10)
    last = None
    log = []

    for t, kind, arg in events:
        # automatic return before processing this event
        if escrow and t >= last + timeout:
            log.append(("TIMEOUT", last + timeout,
                        tuple(sorted(escrow, reverse=True))))
            escrow = []

        if kind == "coin":
            if arg not in ACCEPTED or len(escrow) >= 10:
                log.append(("REJECT", t, arg))
            else:
                escrow.append(arg)
                last = t
        elif kind == "select":
            last = t
            s = arg
            if s not in prices:
                log.append(("UNKNOWN", t, s))
            elif st[s] == 0:
                log.append(("SOLD_OUT", t, s))
            else:
                total = sum(escrow)
                price = prices[s]
                if total < price:
                    log.append(("NEED", t, price - total))
                else:
                    tmp = dict(b)
                    for c in escrow:
                        tmp[c] += 1
                    remaining = total - price
                    change = []
                    for d in DENOMS:
                        k = min(tmp[d], remaining // d)
                        if k:
                            tmp[d] -= k
                            remaining -= k * d
                            change.extend([d] * k)
                    if remaining == 0:
                        b = tmp
                        st[s] -= 1
                        escrow = []
                        log.append(("VEND", t, s, tuple(change)))
                    else:
                        log.append(("EXACT_ONLY", t, s))
        elif kind == "cancel":
            last = t
            if escrow:
                log.append(("RETURN", t, tuple(sorted(escrow, reverse=True))))
                escrow = []

    if escrow:
        log.append(("TIMEOUT", last + timeout,
                    tuple(sorted(escrow, reverse=True))))
        escrow = []

    return log, (b[5], b[10], b[25], b[100])

import re

_NAME = re.compile(r'[a-z0-9_]+')
_PRINC = re.compile(r'(user|group):([a-z0-9_]+)')
_ACTIONS = re.compile(r'[a-z]+(?:,[a-z]+)*')
_WORD = re.compile(r'[a-z]+')
_SEG = re.compile(r'[a-z0-9._-]+')


def evaluate_access(rules, requests) -> list[str]:
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    parsed = []  # (effect_is_deny, ptype, pname, actions(set or None), segs, spec)
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")
        f = rule.split()
        if len(f) != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {len(f)}")
        effect, principal, action, resource = f
        if effect not in ("ALLOW", "DENY"):
            raise ValueError(f"rule {i}: bad effect {effect!r}")
        if principal == "*":
            ptype, pname = None, None
        else:
            m = _PRINC.fullmatch(principal)
            if not m:
                raise ValueError(f"rule {i}: bad principal {principal!r}")
            ptype, pname = m.group(1), m.group(2)
        if action == "*":
            acts = None
        else:
            if not _ACTIONS.fullmatch(action):
                raise ValueError(f"rule {i}: bad action {action!r}")
            acts = set(action.split(","))
        ok = resource.startswith("/")
        segs = []
        if ok and resource != "/":
            segs = resource[1:].split("/")
            for s in segs:
                if s not in ("*", "**") and not _SEG.fullmatch(s):
                    ok = False
                    break
        if not ok:
            raise ValueError(f"rule {i}: bad resource {resource!r}")
        L = sum(1 for s in segs if s != "*" and s != "**")
        P = 2 if ptype == "user" else (1 if ptype == "group" else 0)
        A = 0 if acts is None else 1
        parsed.append((effect == "DENY", ptype, pname, acts, segs, (L, P, A)))

    for j, req in enumerate(requests):
        if not isinstance(req, tuple) or len(req) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")
        user, groups, action, path = req
        if not isinstance(user, str) or not _NAME.fullmatch(user):
            raise ValueError(f"request {j}: bad user {user!r}")
        if not isinstance(groups, list) or not all(
                isinstance(g, str) and _NAME.fullmatch(g) for g in groups):
            raise ValueError(f"request {j}: bad groups")
        if not isinstance(action, str) or not _WORD.fullmatch(action):
            raise ValueError(f"request {j}: bad action {action!r}")
        ok = isinstance(path, str) and path.startswith("/")
        if ok and path != "/":
            ok = all(_SEG.fullmatch(s) for s in path[1:].split("/"))
        if not ok:
            raise ValueError(f"request {j}: bad path {path!r}")

    path_cache = {}

    def rules_for_path(path):
        r = path_cache.get(path)
        if r is not None:
            return r
        psegs = [] if path == "/" else path[1:].split("/")
        n = len(psegs)
        full = (1 << (n + 1)) - 1
        allmask = (1 << n) - 1
        litmask = {}
        for k, s in enumerate(psegs):
            litmask[s] = litmask.get(s, 0) | (1 << k)
        res = []
        for idx, (_, _, _, _, segs, _) in enumerate(parsed):
            state = 1
            for s in segs:
                if s == "**":
                    low = state & -state
                    state = full & ~(low - 1) if low else 0
                else:
                    mk = allmask if s == "*" else litmask.get(s, 0)
                    state = (state & mk) << 1
                if not state:
                    break
            if (state >> n) & 1:
                res.append(idx)
        path_cache[path] = res
        return res

    out = []
    for user, groups, action, path in requests:
        gset = set(groups)
        best = None
        deny_i = None
        allow_i = None
        for idx in rules_for_path(path):
            is_deny, ptype, pname, acts, _, spec = parsed[idx]
            if ptype == "user":
                if pname != user:
                    continue
            elif ptype == "group":
                if pname not in gset:
                    continue
            if acts is not None and action not in acts:
                continue
            if best is None or spec > best:
                best = spec
                deny_i = None
                allow_i = None
            elif spec < best:
                continue
            if is_deny:
                if deny_i is None:
                    deny_i = idx
            else:
                if allow_i is None:
                    allow_i = idx
        if best is None:
            out.append("DENY by default")
        elif deny_i is not None:
            out.append(f"DENY by rule {deny_i}")
        else:
            out.append(f"ALLOW by rule {allow_i}")
    return out

import copy
import json
import re

_IDENT = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _type(v):
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, int):
        return "int"
    if isinstance(v, float):
        return "float"
    if isinstance(v, str):
        return "str"
    if isinstance(v, list):
        return "list"
    if isinstance(v, dict):
        return "dict"
    return type(v).__name__


def _path(p, name):
    if _IDENT.fullmatch(name):
        return p + "." + name
    return p + "[" + json.dumps(name, ensure_ascii=False) + "]"


def _merge(T, O, P, L, warnings):
    for K, V in O.items():
        if not isinstance(K, str):
            raise TypeError(f"layer {L}: non-string key at {P}")
        if K.startswith("-"):
            kind, name = "delete", K[1:]
        elif K.endswith("+"):
            kind, name = "append", K[:-1]
        else:
            kind, name = "set", K
        if name == "":
            raise ValueError(f"layer {L}: empty key name at {P}")
        Q = _path(P, name)
        if kind == "delete":
            if V is not None:
                raise ValueError(f"layer {L}: delete directive needs null at {Q}")
            if name in T:
                del T[name]
            else:
                warnings.append(f"layer {L}: delete of missing key at {Q}")
        elif kind == "append":
            if not isinstance(V, list):
                raise ValueError(f"layer {L}: append directive needs a list at {Q}")
            if name not in T:
                T[name] = copy.deepcopy(V)
            elif isinstance(T[name], list):
                T[name].extend(copy.deepcopy(V))
            else:
                raise ValueError(
                    f"layer {L}: cannot append to {_type(T[name])} at {Q}")
        else:
            if name in T and _type(T[name]) != _type(V):
                warnings.append(
                    f"layer {L}: type change at {Q}: {_type(T[name])} -> {_type(V)}")
            if isinstance(V, dict):
                if name in T and isinstance(T[name], dict):
                    target = T[name]
                else:
                    target = {}
                    T[name] = target
                _merge(target, V, Q, L, warnings)
            else:
                T[name] = copy.deepcopy(V)


def merge_layers(layers):
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")
    result = {}
    warnings = []
    for L, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {L} is not a dict")
        _merge(result, layer, "$", L, warnings)
    return result, warnings

import re
import datetime

_OPEN_RE = re.compile(r"-?(0|[1-9][0-9]{0,8})\.[0-9]{2}")
_AMT_RE = re.compile(r"(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?")
_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def _money(c):
    sign = "-" if c < 0 else ""
    a = abs(c)
    return f"{sign}{a // 100:,}.{a % 100:02d}"


def _parse_amount(s):
    # s already validated against the regex (unsigned)
    if "." in s:
        ip, fp = s.split(".")
        fp = (fp + "00")[:2]
    else:
        ip, fp = s, "00"
    return int(ip) * 100 + int(fp)


def _valid_date(d):
    if not isinstance(d, str):
        return False
    m = _DATE_RE.fullmatch(d)
    if not m:
        return False
    y, mo, da = int(m.group(1)), int(m.group(2)), int(m.group(3))
    if not (1900 <= y <= 2999):
        return False
    try:
        datetime.date(y, mo, da)
    except ValueError:
        return False
    return True


def render_statement(opening, entries):
    if not isinstance(opening, str):
        raise TypeError("opening must be a str")
    if not _OPEN_RE.fullmatch(opening):
        raise ValueError("opening: bad amount " + repr(opening))
    if not isinstance(entries, list):
        raise TypeError("entries must be a list")

    parsed = []
    prev_date = None
    for i, e in enumerate(entries):
        if not isinstance(e, tuple) or len(e) != 4:
            raise TypeError(f"entry {i}: expected 4-tuple")
        date, kind, amount, memo = e
        if not _valid_date(date):
            raise ValueError(f"entry {i}: bad date {date!r}")
        if prev_date is not None and date < prev_date:
            raise ValueError(f"entry {i}: date out of order")
        if not isinstance(kind, str) or kind not in ("credit", "debit", "fee"):
            raise ValueError(f"entry {i}: bad kind {kind!r}")
        if (not isinstance(amount, str) or not _AMT_RE.fullmatch(amount)
                or _parse_amount(amount) == 0):
            raise ValueError(f"entry {i}: bad amount {amount!r}")
        if (not isinstance(memo, str) or not memo.split()
                or any(ord(ch) < 32 or ord(ch) == 127 for ch in memo)):
            raise ValueError(f"entry {i}: bad memo")
        prev_date = date
        parsed.append((date, kind, _parse_amount(amount), memo))

    neg = opening.startswith("-")
    body = opening[1:] if neg else opening
    ip, fp = body.split(".")
    bal = int(ip) * 100 + int(fp)
    if neg:
        bal = -bal

    lines = ["Opening balance: " + _money(bal)]
    counts = {"credit": 0, "debit": 0, "fee": 0}
    fee_dates = set()

    def emit(date, kind, cents, memo):
        nonlocal bal
        if kind == "credit":
            bal += cents
            sign = "+"
        else:
            bal -= cents
            sign = "-"
        counts[kind] += 1
        m = " ".join(memo.split())
        if len(m) > 20:
            m = m[:19] + "~"
        m = m.ljust(20)
        amt = (sign + _money(cents)).rjust(14)
        b = _money(bal).rjust(15)
        flag = " OD" if bal < 0 else ""
        lines.append(f"{date}  {m}  {amt}  {b}{flag}")

    for date, kind, cents, memo in parsed:
        emit(date, kind, cents, memo)
        if kind == "debit" and bal < 0 and date not in fee_dates:
            fee_dates.add(date)
            emit(date, "fee", 2500, "OVERDRAFT FEE")

    lines.append("Closing balance: " + _money(bal))
    lines.append(f"Credits: {counts['credit']}  Debits: {counts['debit']}  Fees: {counts['fee']}")
    return lines

import re

_NUM = r"(0|[1-9][0-9]*)"
_VER_RE = re.compile(_NUM + r"\." + _NUM + r"\." + _NUM + r"(?:~rc([1-9][0-9]*))?")
_MAJ_RE = re.compile(_NUM + r"\.\*")
_MAJMIN_RE = re.compile(_NUM + r"\." + _NUM + r"\.\*")
_AT_RE = re.compile(r"@" + _NUM + r"\." + _NUM)


def _parse_version(s):
    """Return a sortable key, or None if s is not a valid version."""
    m = _VER_RE.fullmatch(s)
    if not m:
        return None
    x, y, z = int(m.group(1)), int(m.group(2)), int(m.group(3))
    if m.group(4) is None:
        return (x, y, z, 1, 0)
    return (x, y, z, 0, int(m.group(4)))


def _parse_clause(c):
    """Return a predicate on version keys, or None if the clause is invalid."""
    if c == "*":
        return lambda k: True
    for op in (">=", "<=", "!=", ">", "<", "="):
        if c.startswith(op):
            v = _parse_version(c[len(op):])
            if v is None:
                return None
            if op == ">=":
                return lambda k, v=v: k >= v
            if op == "<=":
                return lambda k, v=v: k <= v
            if op == "!=":
                return lambda k, v=v: k != v
            if op == ">":
                return lambda k, v=v: k > v
            if op == "<":
                return lambda k, v=v: k < v
            return lambda k, v=v: k == v
    v = _parse_version(c)
    if v is not None:
        return lambda k, v=v: k == v
    m = _MAJ_RE.fullmatch(c)
    if m:
        x = int(m.group(1))
        return lambda k, x=x: k[0] == x
    m = _MAJMIN_RE.fullmatch(c)
    if m:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda k, x=x, y=y: k[0] == x and k[1] == y
    m = _AT_RE.fullmatch(c)
    if m:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda k, x=x, y=y: k[0] == x and k[1] >= y
    return None


def pick_version(available, constraint):
    if not isinstance(available, list):
        raise TypeError("available must be a list")
    keys = []
    for i, el in enumerate(available):
        k = _parse_version(el) if isinstance(el, str) else None
        if k is None:
            raise ValueError(f"invalid version at index {i}: {el!r}")
        keys.append(k)
    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")
    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    alternatives = []  # list of (allows_rc, [predicates])
    for a, alt in enumerate(constraint.split("|"), start=1):
        alt = alt.strip(" ")
        allow_rc = False
        if alt.startswith("?"):
            allow_rc = True
            alt = alt[1:].strip(" ")
        if alt == "":
            raise ValueError(f"alternative {a} is empty")
        preds = []
        for c, clause in enumerate(alt.split(","), start=1):
            clause = clause.strip(" ")
            p = _parse_clause(clause)
            if p is None:
                raise ValueError(
                    f"alternative {a}, clause {c}: invalid clause {clause!r}"
                )
            preds.append(p)
        alternatives.append((allow_rc, preds))

    best_key = None
    best = None
    for s, k in zip(available, keys):
        is_rc = k[3] == 0
        ok = False
        for allow_rc, preds in alternatives:
            if is_rc and not allow_rc:
                continue
            if all(p(k) for p in preds):
                ok = True
                break
        if ok and (best_key is None or k > best_key):
            best_key = k
            best = s
    return best

import re
import sys

_INT_RE = re.compile(r'-?(0|[1-9][0-9]*)')
_KEY_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_-]*')
_ESC = {'\\': '\\', '"': '"', 'n': '\n', 't': '\t'}


def _scalar(text):
    """Returns (value, None) or (None, error_message)."""
    if text.startswith('"'):
        out = []
        i = 1
        n = len(text)
        while i < n:
            c = text[i]
            if c == '\\':
                if i + 1 >= n or text[i + 1] not in _ESC:
                    return None, "bad escape"
                out.append(_ESC[text[i + 1]])
                i += 2
            elif c == '"':
                if i != n - 1:
                    return None, "bad string"
                return ''.join(out), None
            else:
                out.append(c)
                i += 1
        return None, "bad string"
    if text == "true":
        return True, None
    if text == "false":
        return False, None
    if text == "null":
        return None, None
    if _INT_RE.fullmatch(text):
        try:
            return int(text), None
        except ValueError:
            try:
                sys.set_int_max_str_digits(0)
            except Exception:
                pass
            return int(text), None
    return text, None


def parse_outline(text: str) -> tuple:
    lines = text.split("\n")
    root = None
    # stack entries: [indent, kind, container]
    stack = []
    prev_opener = None  # (indent, container, key_or_index)

    for ln, line in enumerate(lines, 1):
        rest = line.lstrip(" \t")
        if rest == "":
            continue
        if rest.startswith("#"):
            continue
        lead = line[:len(line) - len(rest)]
        indent = len(lead)

        if "\t" in lead:
            return ("error", ln, "tab in indentation")

        key = None
        if rest == "-" or rest.startswith("- "):
            kind = "list"
            t = rest[2:].strip(" ")
            opener = (t == "")
        else:
            kind = "map"
            idx = rest.find(":")
            if idx < 0:
                return ("error", ln, "invalid entry")
            key = rest[:idx]
            if not _KEY_RE.fullmatch(key):
                return ("error", ln, "invalid entry")
            after = rest[idx + 1:]
            if after.strip(" ") == "":
                opener = True
                t = ""
            else:
                if after[0] != " ":
                    return ("error", ln, "invalid entry")
                opener = False
                t = after.strip(" ")

        value = None
        if not opener:
            value, err = _scalar(t)
            if err:
                return ("error", ln, err)

        # structure
        new_block = False
        if not stack:
            if indent != 0:
                return ("error", ln, "unexpected indent")
            new_block = True
        elif prev_opener is not None and indent > prev_opener[0]:
            new_block = True

        if new_block:
            cont = {} if kind == "map" else []
            if not stack:
                root = cont
            else:
                _, pc, pk = prev_opener
                pc[pk] = cont
            stack.append([indent, kind, cont])
        else:
            if indent > stack[-1][0]:
                return ("error", ln, "unexpected indent")
            while stack[-1][0] > indent:
                stack.pop()
            if stack[-1][0] != indent:
                return ("error", ln, "inconsistent dedent")
            top = stack[-1]
            if top[1] != kind:
                return ("error", ln, "mixed block")
            if kind == "map" and key in top[2]:
                return ("error", ln, "duplicate key '%s'" % key)

        cont = stack[-1][2]
        if kind == "map":
            cont[key] = value
            ref = key
        else:
            cont.append(value)
            ref = len(cont) - 1
        prev_opener = (indent, cont, ref) if opener else None

    return ("ok", root)

import re, sys

try:
    sys.set_int_max_str_digits(0)
except Exception:
    pass

_TOK = re.compile(r'[\[\]]|[^ \t\n\r\[\]]+')
_INT = re.compile(r'-?[0-9]+')

_BUILTIN = {
    '+': 10, '-': 11, '*': 12, '/': 13, '%': 14, '<': 15, '=': 16,
    'dup': 20, 'drop': 21, 'swap': 22, 'over': 23, 'rot': 24,
    'if': 30, 'times': 31, 'while': 32, 'call': 33, 'dip': 34,
}


def run_pile(src: str, max_steps: int) -> tuple:
    tokens = _TOK.findall(src)
    n = len(tokens)
    # ---------- structure check ----------
    match = {}
    opens = []
    i = 0
    intm = _INT.fullmatch
    while i < n:
        t = tokens[i]
        if t == '[':
            opens.append(i)
        elif t == ']':
            if not opens or tokens[opens[-1]] != '[':
                return ("error", i, "unmatched ]")
            match[opens.pop()] = i
        elif t == ':':
            if opens:
                return ("error", i, "misplaced :")
            if i == n - 1:
                return ("error", i, "unclosed :")
            nm = tokens[i + 1]
            if nm in ('[', ']', ':', ';') or nm in _BUILTIN or intm(nm):
                return ("error", i + 1, "bad name")
            opens.append(i)
            i += 2
            continue
        elif t == ';':
            if not opens or tokens[opens[-1]] != ':':
                return ("error", i, "unmatched ;")
            match[opens.pop()] = i
        i += 1
    if opens:
        j = opens[0]
        return ("error", j, "unclosed [" if tokens[j] == '[' else "unclosed :")

    # ---------- codes ----------
    codes = []
    bget = _BUILTIN.get
    for t in tokens:
        c = bget(t)
        if c is None:
            if t == '[':
                c = 1
            elif t == ':':
                c = 2
            elif t == ']' or t == ';':
                c = 4
            elif intm(t):
                c = 0
            else:
                c = 3
        codes.append(c)

    # ---------- execution ----------
    stack = []
    defs = {}
    frames = [[0, n, 0]]
    steps = 0
    m = match
    while frames:
        f = frames[-1]
        pos = f[0]
        if pos >= f[1]:
            kind = f[2]
            if kind == 0:
                frames.pop()
            elif kind == 1:
                if f[3] > 0:
                    f[3] -= 1
                    f[0] = f[4]
                else:
                    frames.pop()
            elif kind == 2:
                idx, cs, ce, bs, be = f[3]
                if not stack:
                    return ("error", idx, "stack underflow")
                v = stack.pop()
                if type(v) is not int:
                    return ("error", idx, "type error")
                if v == 0:
                    frames.pop()
                elif bs < be:
                    f[0] = bs
                    f[1] = be
                    f[2] = 3
                else:
                    f[0] = cs
                    f[1] = ce
            elif kind == 3:
                idx, cs, ce, bs, be = f[3]
                f[0] = cs
                f[1] = ce
                f[2] = 2
            else:
                frames.pop()
                stack.append(f[3])
            continue
        steps += 1
        if steps > max_steps:
            return ("error", pos, "step limit exceeded")
        c = codes[pos]
        f[0] = pos + 1
        if c == 0:
            stack.append(int(tokens[pos]))
        elif 10 <= c <= 16:
            if len(stack) < 2:
                return ("error", pos, "stack underflow")
            b = stack[-1]
            a = stack[-2]
            if type(a) is not int or type(b) is not int:
                return ("error", pos, "type error")
            if c == 10:
                r = a + b
            elif c == 11:
                r = a - b
            elif c == 12:
                r = a * b
            elif c == 15:
                r = 1 if a < b else 0
            elif c == 16:
                r = 1 if a == b else 0
            else:
                if b == 0:
                    return ("error", pos, "division by zero")
                r = a // b if c == 13 else a % b
            stack.pop()
            stack[-1] = r
        elif c == 20:
            if not stack:
                return ("error", pos, "stack underflow")
            stack.append(stack[-1])
        elif c == 21:
            if not stack:
                return ("error", pos, "stack underflow")
            stack.pop()
        elif c == 22:
            if len(stack) < 2:
                return ("error", pos, "stack underflow")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif c == 23:
            if len(stack) < 2:
                return ("error", pos, "stack underflow")
            stack.append(stack[-2])
        elif c == 24:
            if len(stack) < 3:
                return ("error", pos, "stack underflow")
            a = stack.pop(-3)
            stack.append(a)
        elif c == 1:
            e = m[pos]
            stack.append((pos + 1, e))
            f[0] = e + 1
        elif c == 3:
            d = defs.get(tokens[pos])
            if d is None:
                return ("error", pos, "unknown word '%s'" % tokens[pos])
            if d[0] < d[1]:
                frames.append([d[0], d[1], 0])
        elif c == 2:
            e = m[pos]
            defs[tokens[pos + 1]] = (pos + 2, e)
            f[0] = e + 1
        elif c == 30:
            if len(stack) < 3:
                return ("error", pos, "stack underflow")
            cc = stack[-3]
            t = stack[-2]
            fl = stack[-1]
            if type(cc) is not int or type(t) is not tuple or type(fl) is not tuple:
                return ("error", pos, "type error")
            del stack[-3:]
            q = t if cc != 0 else fl
            if q[0] < q[1]:
                frames.append([q[0], q[1], 0])
        elif c == 31:
            if len(stack) < 2:
                return ("error", pos, "stack underflow")
            q = stack[-2]
            k = stack[-1]
            if type(q) is not tuple or type(k) is not int:
                return ("error", pos, "type error")
            if k < 0:
                return ("error", pos, "negative count")
            del stack[-2:]
            if k > 0 and q[0] < q[1]:
                frames.append([q[0], q[1], 1, k - 1, q[0]])
        elif c == 32:
            if len(stack) < 2:
                return ("error", pos, "stack underflow")
            cq = stack[-2]
            bq = stack[-1]
            if type(cq) is not tuple or type(bq) is not tuple:
                return ("error", pos, "type error")
            del stack[-2:]
            frames.append([cq[0], cq[1], 2, (pos, cq[0], cq[1], bq[0], bq[1])])
        elif c == 33:
            if not stack:
                return ("error", pos, "stack underflow")
            q = stack[-1]
            if type(q) is not tuple:
                return ("error", pos, "type error")
            stack.pop()
            if q[0] < q[1]:
                frames.append([q[0], q[1], 0])
        elif c == 34:
            if len(stack) < 2:
                return ("error", pos, "stack underflow")
            q = stack[-1]
            if type(q) is not tuple:
                return ("error", pos, "type error")
            a = stack[-2]
            del stack[-2:]
            if q[0] < q[1]:
                frames.append([q[0], q[1], 4, a])
            else:
                stack.append(a)
        else:
            # cannot happen after the structure check
            return ("error", pos, "unknown word '%s'" % tokens[pos])

    # ---------- result ----------
    cache = {}

    def conv(q):
        r = cache.get(q)
        if r is not None:
            return r
        root = []
        st = [root]
        for k in range(q[0], q[1]):
            t = tokens[k]
            if t == '[':
                nw = []
                st[-1].append(nw)
                st.append(nw)
            elif t == ']':
                st.pop()
            else:
                st[-1].append(t)
        cache[q] = root
        return root

    out = []
    for v in stack:
        if type(v) is tuple:
            out.append(conv(v))
        else:
            out.append(v)
    return ("ok", out)

import sys
import operator


def filter_records(query: str, records: list) -> tuple:
    try:
        sys.set_int_max_str_digits(0)
    except Exception:
        pass

    n = len(query)
    KEYWORDS = {"and", "or", "not", "in", "has"}
    toks = []  # (kind, value, start, end)
    i = 0
    wordstart = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_")
    digits = set("0123456789")
    wordchars = wordstart | digits | {"."}

    # ---------- LEXING ----------
    while i < n:
        c = query[i]
        if c in " \t\n":
            i += 1
        elif c in "()[],":
            toks.append((c, c, i, i + 1))
            i += 1
        elif c in "=<>!":
            if i + 1 < n and query[i + 1] == "=" and c in "!<>":
                toks.append(("op", c + "=", i, i + 2))
                i += 2
            elif c == "!":
                return ("error", i, "unexpected character '!'")
            else:
                toks.append(("op", c, i, i + 1))
                i += 1
        elif c in digits or (c == "-" and i + 1 < n and query[i + 1] in digits):
            j = i + 1
            while j < n and query[j] in digits:
                j += 1
            toks.append(("int", int(query[i:j]), i, j))
            i = j
        elif c == '"':
            j = i + 1
            buf = []
            closed = False
            while j < n:
                d = query[j]
                if d == "\\":
                    if j + 1 < n and query[j + 1] in '"\\':
                        buf.append(query[j + 1])
                        j += 2
                    else:
                        return ("error", j, "bad escape")
                elif d == '"':
                    closed = True
                    j += 1
                    break
                else:
                    buf.append(d)
                    j += 1
            if not closed:
                return ("error", i, "unterminated string")
            toks.append(("str", "".join(buf), i, j))
            i = j
        elif c in wordstart:
            j = i + 1
            while j < n and query[j] in wordchars:
                j += 1
            w = query[i:j]
            if w in KEYWORDS:
                toks.append(("kw", w, i, j))
            else:
                toks.append(("field", w, i, j))
            i = j
        else:
            return ("error", i, "unexpected character '%s'" % c)
    toks.append(("END", None, n, n))

    # ---------- PARSING (iterative, to RPN) ----------
    def err(t):
        if t[0] == "END":
            return ("error", t[2], "unexpected end of input")
        return ("error", t[2], "unexpected token '%s'" % query[t[2]:t[3]])

    CMP = {"=": operator.eq, "!=": operator.ne, "<": operator.lt,
           "<=": operator.le, ">": operator.gt, ">=": operator.ge}
    PREC = {"not": 3, "and": 2, "or": 1}
    # RPN codes: 0 cmp, 1 in, 2 has, 3 not, 4 and, 5 or
    out = []
    ops = []
    p = 0
    expect_operand = True
    while True:
        t = toks[p]
        k = t[0]
        if expect_operand:
            if k == "kw" and t[1] == "not":
                ops.append("not")
                p += 1
            elif k == "(":
                ops.append("(")
                p += 1
            elif k == "kw" and t[1] == "has":
                t2 = toks[p + 1]
                if t2[0] != "field":
                    return err(t2)
                out.append((2, t2[1]))
                p += 2
                expect_operand = False
            elif k == "field":
                name = t[1]
                t2 = toks[p + 1]
                if t2[0] == "op":
                    t3 = toks[p + 2]
                    if t3[0] not in ("int", "str"):
                        return err(t3)
                    out.append((0, name, CMP[t2[1]], t2[1], t3[1], type(t3[1])))
                    p += 3
                    expect_operand = False
                elif t2[0] == "kw" and t2[1] == "in":
                    t3 = toks[p + 2]
                    if t3[0] != "[":
                        return err(t3)
                    q = p + 3
                    items = set()
                    while True:
                        tl = toks[q]
                        if tl[0] not in ("int", "str"):
                            return err(tl)
                        items.add((type(tl[1]), tl[1]))
                        tn = toks[q + 1]
                        if tn[0] == ",":
                            q += 2
                        elif tn[0] == "]":
                            q += 2
                            break
                        else:
                            return err(tn)
                    out.append((1, name, items))
                    p = q
                    expect_operand = False
                else:
                    return err(t2)
            else:
                return err(t)
        else:
            if k == "kw" and t[1] in ("and", "or"):
                pr = PREC[t[1]]
                while ops and ops[-1] != "(" and PREC[ops[-1]] >= pr:
                    o = ops.pop()
                    out.append((3,) if o == "not" else (4,) if o == "and" else (5,))
                ops.append(t[1])
                p += 1
                expect_operand = True
            elif k == ")":
                found = False
                while ops:
                    o = ops.pop()
                    if o == "(":
                        found = True
                        break
                    out.append((3,) if o == "not" else (4,) if o == "and" else (5,))
                if not found:
                    return err(t)
                p += 1
            elif k == "END":
                if "(" in ops:
                    return err(t)
                while ops:
                    o = ops.pop()
                    out.append((3,) if o == "not" else (4,) if o == "and" else (5,))
                break
            else:
                return err(t)

    # ---------- EVALUATION ----------
    # 0 FALSE, 1 UNKNOWN, 2 TRUE
    res = []
    MISSING = object()
    for idx, rec in enumerate(records):
        st = []
        push = st.append
        for ins in out:
            c = ins[0]
            if c == 0:
                v = rec.get(ins[1], MISSING)
                if v is MISSING:
                    push(1)
                elif type(v) is ins[5]:
                    push(2 if ins[2](v, ins[4]) else 0)
                else:
                    o = ins[3]
                    if o == "=":
                        push(0)
                    elif o == "!=":
                        push(2)
                    else:
                        push(1)
            elif c == 1:
                v = rec.get(ins[1], MISSING)
                if v is MISSING:
                    push(1)
                else:
                    push(2 if (type(v), v) in ins[2] else 0)
            elif c == 2:
                push(2 if ins[1] in rec else 0)
            elif c == 3:
                st[-1] = 2 - st[-1]
            elif c == 4:
                b = st.pop()
                if b < st[-1]:
                    st[-1] = b
            else:
                b = st.pop()
                if b > st[-1]:
                    st[-1] = b
        if st[-1] == 2:
            res.append(idx)
    return ("ok", res)

import re
import sys

try:
    sys.set_int_max_str_digits(0)
except Exception:
    pass

_TOK = re.compile(
    r'([0-9]+)|([a-z_][a-z0-9_]*)|(<=|>=|==|!=)|([-+*/%^()?:<>])| +|(.)', re.S)

(S_COND, S_CMP, S_SUM, S_TERM, S_UNARY, S_POWER, S_ATOM, S_PTAIL, S_TTAIL,
 S_STAIL, S_CTAIL, S_CONDTAIL, S_COLON, S_RPAREN, S_END) = range(15)

K_INT, K_NAME, K_NEG, K_BIN, K_TERN, K_POW, A_NEG, A_BIN, A_POW, A_TERN = range(10)

_CMPOPS = ('<', '<=', '>', '>=', '==', '!=')


def evaluate(src, env):
    # ---- tokenize ----
    toks = []
    for m in _TOK.finditer(src):
        g = m.lastindex
        if g is None:
            continue
        text = m.group()
        if g == 1:
            toks.append(('INT', text, m.start()))
        elif g == 2:
            toks.append(('NAME', text, m.start()))
        elif g == 3 or g == 4:
            toks.append((text, text, m.start()))
        else:
            toks.append(('BAD', text, m.start()))
    toks.append(('END', '', len(src)))

    def err(tok):
        t, text, pos = tok
        if t == 'END':
            return ("error", pos, "unexpected end of input")
        if t == 'BAD':
            return ("error", pos, "unexpected character '%s'" % text)
        return ("error", pos, "unexpected token '%s'" % text)

    # ---- parse ----
    i = 0
    out = []
    stack = [S_END, S_COND]
    while stack:
        s = stack.pop()
        tok = toks[i]
        t = tok[0]
        if type(s) is tuple:
            tag = s[0]
            if tag == 'neg':
                out.append((K_NEG, out.pop()))
            elif tag == 'bin':
                r = out.pop()
                l = out.pop()
                out.append((K_BIN, s[1], s[2], l, r))
            elif tag == 'pow':
                r = out.pop()
                l = out.pop()
                out.append((K_POW, s[1], l, r))
            else:  # tern
                b = out.pop()
                a = out.pop()
                c = out.pop()
                out.append((K_TERN, c, a, b))
            continue
        if s == S_COND:
            stack.append(S_CONDTAIL)
            stack.append(S_CMP)
        elif s == S_CMP:
            stack.append(S_CTAIL)
            stack.append(S_SUM)
        elif s == S_SUM:
            stack.append(S_STAIL)
            stack.append(S_TERM)
        elif s == S_TERM:
            stack.append(S_TTAIL)
            stack.append(S_UNARY)
        elif s == S_UNARY:
            if t == '-':
                i += 1
                stack.append(('neg',))
                stack.append(S_UNARY)
            else:
                stack.append(S_POWER)
        elif s == S_POWER:
            stack.append(S_PTAIL)
            stack.append(S_ATOM)
        elif s == S_ATOM:
            if t == 'INT':
                out.append((K_INT, tok[1]))
                i += 1
            elif t == 'NAME':
                out.append((K_NAME, tok[1], tok[2]))
                i += 1
            elif t == '(':
                i += 1
                stack.append(S_RPAREN)
                stack.append(S_COND)
            else:
                return err(tok)
        elif s == S_PTAIL:
            if t == '^':
                i += 1
                stack.append(('pow', tok[2]))
                stack.append(S_UNARY)
        elif s == S_TTAIL:
            if t == '*' or t == '/' or t == '%':
                i += 1
                stack.append(S_TTAIL)
                stack.append(('bin', t, tok[2]))
                stack.append(S_UNARY)
        elif s == S_STAIL:
            if t == '+' or t == '-':
                i += 1
                stack.append(S_STAIL)
                stack.append(('bin', t, tok[2]))
                stack.append(S_TERM)
        elif s == S_CTAIL:
            if t in _CMPOPS:
                i += 1
                stack.append(('bin', t, tok[2]))
                stack.append(S_SUM)
        elif s == S_CONDTAIL:
            if t == '?':
                i += 1
                stack.append(('tern',))
                stack.append(S_COND)
                stack.append(S_COLON)
                stack.append(S_COND)
        elif s == S_COLON:
            if t == ':':
                i += 1
            else:
                return err(tok)
        elif s == S_RPAREN:
            if t == ')':
                i += 1
            else:
                return err(tok)
        else:  # S_END
            if t != 'END':
                return err(tok)

    root = out[0]

    # ---- evaluate ----
    work = [root]
    vals = []
    while work:
        item = work.pop()
        k = item[0]
        if k == K_INT:
            vals.append(int(item[1]))
        elif k == K_NAME:
            name = item[1]
            if name in env:
                vals.append(env[name])
            else:
                return ("error", item[2], "unknown name '%s'" % name)
        elif k == K_NEG:
            work.append((A_NEG,))
            work.append(item[1])
        elif k == K_BIN:
            work.append((A_BIN, item[1], item[2]))
            work.append(item[4])
            work.append(item[3])
        elif k == K_POW:
            work.append((A_POW, item[1]))
            work.append(item[3])
            work.append(item[2])
        elif k == K_TERN:
            work.append((A_TERN, item[2], item[3]))
            work.append(item[1])
        elif k == A_NEG:
            vals.append(-vals.pop())
        elif k == A_TERN:
            c = vals.pop()
            work.append(item[1] if c != 0 else item[2])
        elif k == A_POW:
            e = vals.pop()
            b = vals.pop()
            if e < 0:
                return ("error", item[1], "negative exponent")
            if e > 256:
                return ("error", item[1], "exponent too large")
            vals.append(b ** e)
        else:  # A_BIN
            op = item[1]
            r = vals.pop()
            l = vals.pop()
            if op == '+':
                v = l + r
            elif op == '-':
                v = l - r
            elif op == '*':
                v = l * r
            elif op == '/':
                if r == 0:
                    return ("error", item[2], "division by zero")
                v = l // r
            elif op == '%':
                if r == 0:
                    return ("error", item[2], "division by zero")
                v = l % r
            elif op == '<':
                v = 1 if l < r else 0
            elif op == '<=':
                v = 1 if l <= r else 0
            elif op == '>':
                v = 1 if l > r else 0
            elif op == '>=':
                v = 1 if l >= r else 0
            elif op == '==':
                v = 1 if l == r else 0
            else:
                v = 1 if l != r else 0
            vals.append(v)
    return ("ok", vals[0])

import decimal
from decimal import Decimal
import math

_DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def _int_to_base(v: int, base: int) -> str:
    if v == 0:
        return "0"
    out = []
    while v:
        v, r = divmod(v, base)
        out.append(_DIGITS[r])
    out.reverse()
    return "".join(out)


def format_base(p: int, q: int, base: int, k: int) -> str:
    if q == 0:
        raise ValueError("q must be nonzero")
    if not (2 <= base <= 36):
        raise ValueError("base must be in 2..36")
    if k < 0:
        raise ValueError("k must be non-negative")

    neg = (p < 0) != (q < 0)
    P = abs(p)
    Q = abs(q)
    if P == 0:
        return "0"

    # Number of decimal digits needed (generous margin)
    prec = int(k * math.log10(base)) + len(str(P)) + 60
    prec = min(prec, decimal.MAX_PREC)
    ctx = decimal.Context(prec=prec, Emax=decimal.MAX_EMAX,
                          Emin=decimal.MIN_EMIN, traps=[decimal.InvalidOperation,
                                                        decimal.DivisionByZero,
                                                        decimal.Overflow])
    with decimal.localcontext(ctx):
        dbase = Decimal(base)
        Bk = dbase ** k if k > 0 else Decimal(1)
        num = Decimal(P) * Bk
        den = Decimal(Q)
        Nq, R = divmod(num, den)
        twoR = R * 2
        if twoR > den or (twoR == den and (Nq % 2) != 0):
            Nq = Nq + 1
        N = Nq
        if N == 0:
            return "0"

        ip, F = divmod(N, Bk)
        int_str = _int_to_base(int(ip), base)

        frac_str = ""
        if F != 0:
            if base == 10:
                frac_str = str(F).zfill(k)
            else:
                L = 16
                pw = {}

                def getpw(h):
                    r = pw.get(h)
                    if r is None:
                        if h == L:
                            r = dbase ** L
                        else:
                            half = getpw(h // 2)
                            r = half * half
                        pw[h] = r
                    return r

                def leaf(v, n):
                    out = []
                    for _ in range(n):
                        v, r = divmod(v, base)
                        out.append(_DIGITS[r])
                    out.reverse()
                    return "".join(out)

                def rec(f, n):
                    if n <= L:
                        return leaf(int(f), n)
                    h = L
                    while h * 2 < n:
                        h *= 2
                    hi, lo = divmod(f, getpw(h))
                    return rec(hi, n - h) + rec(lo, h)

                frac_str = rec(F, k)
            frac_str = frac_str.rstrip("0")

    res = int_str
    if frac_str:
        res += "." + frac_str
    if neg:
        res = "-" + res
    return res

import re
from fractions import Fraction

_PAT = re.compile(r'([+-]?)([0-9]+\.?[0-9]*|\.[0-9]+)(?:[eE]([+-]?[0-9]+))?')


def closest_fraction(x: str, max_num: int, max_den: int) -> str:
    if not isinstance(x, str):
        raise ValueError("bad literal")
    m = _PAT.fullmatch(x)
    if m is None or max_num < 0 or max_den < 1:
        raise ValueError("invalid input")
    sign, mant, ex = m.group(1), m.group(2), m.group(3)
    ex = int(ex) if ex else 0
    if '.' in mant:
        ip, fp = mant.split('.')
    else:
        ip, fp = mant, ''
    digits = int((ip + fp) or '0')
    e = ex - len(fp)
    if e >= 0:
        val = Fraction(digits * 10 ** e)
    else:
        val = Fraction(digits, 10 ** (-e))
    neg = sign == '-'
    N, D = max_num, max_den

    def fmt(p, q):
        if p == 0:
            return "0/1"
        return ("-" if neg else "") + f"{p}/{q}"

    if val == 0:
        return "0/1"
    if val >= N:
        return fmt(N, 1)

    P, Q = val.numerator, val.denominator
    p1, q1 = 0, 1   # lower (<= x)
    p2, q2 = 1, 0   # upper (> x)
    while True:
        mp, mq = p1 + p2, q1 + q2
        if mp > N or mq > D:
            break
        # compare mediant with x: mp/mq <= P/Q ?
        if mp * Q <= P * mq:
            # move lower: p1 + k p2
            num = P * q1 - Q * p1
            den = Q * p2 - P * q2   # > 0
            k = num // den
            if p2 > 0:
                k = min(k, (N - p1) // p2)
            if q2 > 0:
                k = min(k, (D - q1) // q2)
            p1, q1 = p1 + k * p2, q1 + k * q2
        else:
            # move upper: p2 + k p1
            num = Q * p2 - P * q2   # > 0
            den = P * q1 - Q * p1   # >= 0
            INF = 1 << 200
            k = num // den if den > 0 else INF
            # strict: need upper > x ... keep >= x is fine, but use > to stay consistent
            if den > 0 and num % den == 0:
                k -= 1  # keep U strictly above x (equality handled by lower side)
            if p1 > 0:
                k = min(k, (N - p2) // p1)
            if q1 > 0:
                k = min(k, (D - q2) // q1)
            if k < 1:
                # mediant is > x and valid, so k>=1 must hold; safeguard
                k = 1
            p2, q2 = p2 + k * p1, q2 + k * q1

    L = Fraction(p1, q1)
    if L == val:
        return fmt(p1, q1)
    if q2 == 0:
        return fmt(p1, q1)
    U = Fraction(p2, q2)
    dL = val - L
    dU = U - val
    if dL < dU:
        return fmt(p1, q1)
    if dU < dL:
        return fmt(p2, q2)
    if q1 != q2:
        return fmt(p1, q1) if q1 < q2 else fmt(p2, q2)
    return fmt(p1, q1) if p1 <= p2 else fmt(p2, q2)

import re

_RE = re.compile(r'([+-]?)([0-9]+\.?[0-9]*|\.[0-9]+)(?:[eE]([+-]?[0-9]+))?')


def decimal_to_half_bits(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    m = _RE.fullmatch(s)
    if not m:
        raise ValueError("bad literal")
    sign_s, mant, exp_s = m.groups()
    sign = 0x8000 if sign_s == '-' else 0

    if '.' in mant:
        ip, fp = mant.split('.')
    else:
        ip, fp = mant, ''

    # exponent (avoid huge int conversions)
    if exp_s:
        esign = -1 if exp_s[0] == '-' else 1
        digs = exp_s.lstrip('+-').lstrip('0')
        if len(digs) > 9:
            ex = esign * 10 ** 10
        elif digs:
            ex = esign * int(digs)
        else:
            ex = 0
    else:
        ex = 0

    E = ex - len(fp)
    d = (ip + fp).lstrip('0')
    if not d:
        return sign
    stripped = d.rstrip('0')
    E += len(d) - len(stripped)
    d = stripped
    if len(d) > 60:
        E += len(d) - 61
        d = d[:60] + '1'   # sticky digit: value is strictly above the truncation
    L = len(d)

    if E + L > 6:
        return sign | 0x7C00
    if E + L < -9:
        return sign

    N = int(d)
    if E >= 0:
        num, den = N * 10 ** E, 1
    else:
        num, den = N, 10 ** (-E)

    # find e with 2**e <= num/den < 2**(e+1)
    e = num.bit_length() - den.bit_length()
    if e >= 0:
        less = num < (den << e)
    else:
        less = (num << (-e)) < den
    if less:
        e -= 1

    ee = max(e, -14)
    q = ee - 10
    if q < 0:
        n2, d2 = num << (-q), den
    else:
        n2, d2 = num, den << q
    k, r = divmod(n2, d2)
    r2 = 2 * r
    if r2 > d2 or (r2 == d2 and (k & 1)):
        k += 1

    pattern = k + ((ee + 14) << 10)
    if pattern >= 0x7C00:
        pattern = 0x7C00
    return sign | pattern

from bisect import bisect_left, bisect_right, insort

def run_ops(ops):
    INF = 1 << 60
    # offline compression of possible start positions
    allS = sorted({op[1] for op in ops if op[0] == "book" and op[1] < op[2]})
    cid = {v: i for i, v in enumerate(allS)}
    m = len(allS)
    size = 1
    while size < max(m, 1):
        size <<= 1
    tree = [-1] * (2 * size)
    fen = [0] * (m + 1)

    def fen_add(i, v):
        i += 1
        while i <= m:
            fen[i] += v
            i += i & -i

    def fen_sum(c):  # sum of first c positions
        r = 0
        while c > 0:
            r += fen[c]
            c -= c & -c
        return r

    def setg(idx, v):
        i = idx + size
        tree[i] = v
        i >>= 1
        while i:
            a = tree[2 * i]
            b = tree[2 * i + 1]
            tree[i] = a if a > b else b
            i >>= 1

    def find_first(k, d):
        i = k + size
        while True:
            if tree[i] >= d:
                break
            while i & 1:
                i >>= 1
            i += 1
        while i < size:
            i <<= 1
            if tree[i] < d:
                i += 1
        return i - size

    starts = []
    end = {}

    def F(x):
        c = bisect_left(allS, x)
        total = fen_sum(c)
        i = bisect_left(starts, x) - 1
        if i >= 0:
            e = end[starts[i]]
            if e > x:
                total -= e - x
        return total

    out = []
    for op in ops:
        k = op[0]
        if k == "book":
            s, e = op[1], op[2]
            if s >= e:
                out.append("INVALID")
                continue
            i = bisect_left(starts, e) - 1
            if i >= 0 and end[starts[i]] > s:
                out.append("CONFLICT")
                continue
            pos = bisect_left(starts, s)
            starts.insert(pos, s)
            end[s] = e
            if pos + 1 < len(starts):
                g = starts[pos + 1] - e
            else:
                g = INF
            setg(cid[s], g)
            if pos > 0:
                p = starts[pos - 1]
                setg(cid[p], s - end[p])
            fen_add(cid[s], e - s)
            out.append(True)
        elif k == "cancel":
            s = op[1]
            if s not in end:
                out.append(0)
                continue
            e = end.pop(s)
            pos = bisect_left(starts, s)
            starts.pop(pos)
            setg(cid[s], -1)
            if pos > 0:
                p = starts[pos - 1]
                if pos < len(starts):
                    setg(cid[p], starts[pos] - end[p])
                else:
                    setg(cid[p], INF)
            fen_add(cid[s], -(e - s))
            out.append(e - s)
        elif k == "first_fit":
            t, d = op[1], op[2]
            p = t
            i = bisect_right(starts, t) - 1
            if i >= 0 and end[starts[i]] > t:
                p = end[starts[i]]
            j = bisect_left(starts, p)
            if j >= len(starts):
                out.append(p)
                continue
            if starts[j] - p >= d:
                out.append(p)
                continue
            idx = find_first(cid[starts[j]], d)
            out.append(end[allS[idx]])
        else:
            a, b = op[1], op[2]
            if a >= b:
                out.append(0)
            else:
                out.append((b - a) - (F(b) - F(a)))
    return out

from collections import OrderedDict
import heapq


def run_cache(capacity, ops):
    if not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be a positive int")

    store = OrderedDict()  # key -> [value, expires_at or None, version]; LRU first
    heap = []              # (expires_at, version, key), lazily invalidated
    out = []
    last_t = None
    version = 0

    for op in ops:
        kind, t = op[0], op[1]
        if last_t is not None and t < last_t:
            raise ValueError("operations must have non-decreasing timestamps")
        last_t = t

        if kind == "put":
            _, _, key, value, ttl = op
            if ttl is not None and (not isinstance(ttl, int) or ttl < 1):
                raise ValueError("ttl must be None or a positive int")
        elif kind != "get" and kind != "size":
            raise ValueError("unknown operation %r" % (kind,))

        # remove everything that has expired at time t
        while heap and heap[0][0] <= t:
            _, ver, k = heapq.heappop(heap)
            e = store.get(k)
            if e is not None and e[2] == ver:
                del store[k]

        if kind == "put":
            expires_at = None if ttl is None else t + ttl
            version += 1
            entry = store.get(key)
            if entry is not None:
                entry[0] = value
                entry[1] = expires_at
                entry[2] = version
                store.move_to_end(key)
            else:
                if len(store) >= capacity:
                    store.popitem(last=False)
                store[key] = [value, expires_at, version]
            if expires_at is not None:
                heapq.heappush(heap, (expires_at, version, key))

        elif kind == "get":
            key = op[2]
            entry = store.get(key)
            if entry is None:
                out.append(None)
            else:
                store.move_to_end(key)
                out.append(entry[0])

        else:  # size
            out.append(len(store))

    return out

import heapq
from collections import defaultdict


def window_medians(readings, k):
    if not isinstance(k, int) or isinstance(k, bool) or k < 1:
        raise ValueError("k must be a positive int")

    low = []    # max-heap via negation: smaller half, top is the (lower) median
    high = []   # min-heap: larger half
    delayed = defaultdict(int)  # value -> pending lazy deletions
    sizes = {"low": 0, "high": 0}  # live element counts
    out = []

    def prune(heap, sign):
        while heap:
            v = sign * heap[0]
            if delayed.get(v, 0):
                delayed[v] -= 1
                heapq.heappop(heap)
            else:
                break

    def rebalance():
        # invariant: sizes["low"] == sizes["high"] or sizes["low"] == sizes["high"] + 1
        if sizes["low"] > sizes["high"] + 1:
            heapq.heappush(high, -heapq.heappop(low))
            sizes["low"] -= 1
            sizes["high"] += 1
        elif sizes["low"] < sizes["high"]:
            heapq.heappush(low, -heapq.heappop(high))
            sizes["high"] -= 1
            sizes["low"] += 1
        prune(low, -1)
        prune(high, 1)

    def add(x):
        if not low or x <= -low[0]:
            heapq.heappush(low, -x)
            sizes["low"] += 1
        else:
            heapq.heappush(high, x)
            sizes["high"] += 1
        rebalance()

    def remove(x):
        # x is guaranteed to be a live element in the window; tops are pruned
        delayed[x] += 1
        if x <= -low[0]:
            sizes["low"] -= 1
        else:
            sizes["high"] -= 1
        prune(low, -1)   # low first: resolves equal-valued top ambiguity
        prune(high, 1)
        rebalance()

    for i, x in enumerate(readings):
        if x is not None:
            add(x)
        if i >= k:
            old = readings[i - k]
            if old is not None:
                remove(old)
        out.append(-low[0] if sizes["low"] else None)
    return out

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "->")
ONE_CHAR_OPS = "<>=+-*/(),"
ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_ident_char(ch):
    return _is_ident_start(ch) or _is_digit(ch)


def tokenize(src):
    tokens = []
    n = len(src)
    i, line, col = 0, 1, 1

    def fail(at_line, at_col, message):
        raise ValueError("line %d col %d: %s" % (at_line, at_col, message))

    while i < n:
        ch = src[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue
        if ch == " " or ch == "\t":
            i += 1
            col += 1
            continue
        if ch == "#":
            end = src.find("\n", i)
            i = n if end == -1 else end
            continue

        if _is_digit(ch):
            j = i
            while j < n and _is_digit(src[j]):
                j += 1
            is_float = False
            if j + 1 < n and src[j] == "." and _is_digit(src[j + 1]):
                j += 1
                while j < n and _is_digit(src[j]):
                    j += 1
                is_float = True
            if j < n and src[j] in "eE":
                k = j + 1
                if k < n and src[k] in "+-":
                    k += 1
                if k < n and _is_digit(src[k]):
                    while k < n and _is_digit(src[k]):
                        k += 1
                    j = k
                    is_float = True
            text = src[i:j]
            tokens.append(("NUMBER", float(text) if is_float else int(text), line, col))
            col += j - i
            i = j
            continue

        if _is_ident_start(ch):
            j = i
            while j < n and _is_ident_char(src[j]):
                j += 1
            tokens.append(("IDENT", src[i:j], line, col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            chars = []
            while True:
                if j >= n or src[j] == "\n":
                    fail(line, col, "unterminated string")
                c = src[j]
                if c == '"':
                    j += 1
                    break
                if c == "\\":
                    if j + 1 >= n or src[j + 1] == "\n":
                        fail(line, col, "unterminated string")
                    if src[j + 1] not in ESCAPES:
                        fail(line, col + (j - i), "bad escape")
                    chars.append(ESCAPES[src[j + 1]])
                    j += 2
                    continue
                chars.append(c)
                j += 1
            tokens.append(("STRING", "".join(chars), line, col))
            col += j - i
            i = j
            continue

        if src[i:i + 2] in TWO_CHAR_OPS:
            tokens.append(("OP", src[i:i + 2], line, col))
            i += 2
            col += 2
            continue
        if ch in ONE_CHAR_OPS:
            tokens.append(("OP", ch, line, col))
            i += 1
            col += 1
            continue

        fail(line, col, "unexpected character %r" % ch)

    return tokens
